package ai.sakana.aura.gallery.domain.recognition

import kotlin.math.sqrt
import kotlin.random.Random

/** A normalized semantic feature vector generated by one specific on-device model version. */
data class SceneEmbedding(
    val mediaUri: String,
    val modelVersion: String,
    val vector: FloatArray,
)

data class SceneCluster(
    val mediaUris: List<String>,
    val averageSimilarity: Float,
)

/**
 * Groups visually related media without using filenames, dates, people or folder names.
 * Candidate discovery uses deterministic random-hyperplane LSH; exact cosine similarity
 * is then applied before union-find. Vectors from different model versions never mix.
 */
class SceneSimilarityClusterer(
    private val threshold: Float = DEFAULT_THRESHOLD,
    private val bands: Int = DEFAULT_BANDS,
    private val bitsPerBand: Int = DEFAULT_BITS_PER_BAND,
) {
    init {
        require(threshold in -1f..1f)
        require(bands > 0 && bitsPerBand in 1..16)
    }

    fun cluster(embeddings: List<SceneEmbedding>): List<SceneCluster> {
        val valid = embeddings
            .asSequence()
            .filter { it.mediaUri.isNotBlank() && it.modelVersion.isNotBlank() }
            .filter { it.vector.isNotEmpty() && it.vector.all(Float::isFinite) }
            .filter { squaredMagnitude(it.vector) > EPSILON }
            .distinctBy(SceneEmbedding::mediaUri)
            .sortedBy(SceneEmbedding::mediaUri)
            .toList()
        if (valid.size < 2) return emptyList()

        val union = DisjointSet(valid.size)
        val partitions = valid.indices.groupBy { index ->
            valid[index].modelVersion to valid[index].vector.size
        }
        partitions.forEach { (partition, indices) ->
            if (indices.size < 2) return@forEach
            val dimension = partition.second
            val candidatePairs = candidatePairs(valid, indices, dimension, partition.first)
            candidatePairs.forEach { pair ->
                val left = (pair ushr 32).toInt()
                val right = (pair and 0xFFFF_FFFFL).toInt()
                val similarity = cosine(valid[left].vector, valid[right].vector) ?: return@forEach
                if (similarity >= threshold) union.join(left, right)
            }
        }

        return valid.indices.groupBy(union::root)
            .values
            .filter { it.size > 1 }
            .map { members ->
                val sortedMembers = members.sortedBy { valid[it].mediaUri }
                val centroid = FloatArray(valid[sortedMembers.first()].vector.size)
                sortedMembers.forEach { member ->
                    valid[member].vector.forEachIndexed { dimension, value -> centroid[dimension] += value / sortedMembers.size }
                }
                val centroidNorm = sqrt(centroid.sumOf { value -> value.toDouble() * value.toDouble() }).toFloat()
                if (centroidNorm > 1e-8f) centroid.indices.forEach { dimension -> centroid[dimension] /= centroidNorm }
                val averageSimilarity = sortedMembers.mapNotNull { member ->
                    cosine(valid[member].vector, centroid)
                }.average().takeIf { it.isFinite() }?.toFloat() ?: 0f
                SceneCluster(
                    mediaUris = sortedMembers.map { valid[it].mediaUri },
                    averageSimilarity = averageSimilarity,
                )
            }
            .sortedBy { it.mediaUris.first() }
    }

    private fun candidatePairs(
        embeddings: List<SceneEmbedding>,
        indices: List<Int>,
        dimension: Int,
        modelVersion: String,
    ): Set<Long> {
        if (indices.size <= SMALL_PARTITION_LIMIT) {
            return buildSet {
                for (i in 0 until indices.lastIndex) {
                    for (j in i + 1 until indices.size) add(pairKey(indices[i], indices[j]))
                }
            }
        }

        val projections = projections(dimension, modelVersion)
        val buckets = HashMap<Long, MutableList<Int>>()
        indices.forEach { index ->
            val signatures = signatures(embeddings[index].vector, projections)
            signatures.forEachIndexed { band, signature ->
                val key = (band.toLong() shl 32) or signature.toLong()
                buckets.getOrPut(key) { ArrayList() } += index
            }
        }
        return buildSet {
            buckets.values.forEach { bucket ->
                for (i in 0 until bucket.lastIndex) {
                    val windowEnd = minOf(bucket.size, i + MAX_NEIGHBORS_PER_BUCKET + 1)
                    for (j in i + 1 until windowEnd) add(pairKey(bucket[i], bucket[j]))
                }
            }
        }
    }

    private fun projections(dimension: Int, modelVersion: String): Array<FloatArray> {
        val seed = modelVersion.fold(0x4A17L) { acc, char -> acc * 31L + char.code }
        return Array(bands * bitsPerBand) { projection ->
            val random = Random(seed xor (projection.toLong() * 0x9E3779B97F4A7C15UL.toLong()))
            FloatArray(dimension) { random.nextFloat() * 2f - 1f }
        }
    }

    private fun signatures(vector: FloatArray, projections: Array<FloatArray>): IntArray {
        val bits = IntArray(projections.size)
        projections.forEachIndexed { index, projection ->
            var dot = 0.0
            for (dimension in vector.indices) dot += vector[dimension] * projection[dimension]
            if (dot >= 0.0) bits[index] = 1
        }
        return IntArray(bands) { band ->
            var signature = 0
            for (bit in 0 until bitsPerBand) {
                if (bits[band * bitsPerBand + bit] == 1) signature = signature or (1 shl bit)
            }
            signature
        }
    }

    private class DisjointSet(size: Int) {
        private val parent = IntArray(size) { it }
        private val rank = IntArray(size)

        fun root(value: Int): Int {
            if (parent[value] != value) parent[value] = root(parent[value])
            return parent[value]
        }

        fun join(left: Int, right: Int) {
            var leftRoot = root(left)
            var rightRoot = root(right)
            if (leftRoot == rightRoot) return
            if (rank[leftRoot] < rank[rightRoot]) leftRoot = rightRoot.also { rightRoot = leftRoot }
            parent[rightRoot] = leftRoot
            if (rank[leftRoot] == rank[rightRoot]) rank[leftRoot]++
        }
    }

    companion object {
        const val DEFAULT_THRESHOLD = 0.90f
        const val DEFAULT_BANDS = 8
        const val DEFAULT_BITS_PER_BAND = 8
        private const val SMALL_PARTITION_LIMIT = 256
        private const val MAX_NEIGHBORS_PER_BUCKET = 16
        private const val EPSILON = 1e-12

        fun cosine(left: FloatArray, right: FloatArray): Float? {
            if (left.isEmpty() || left.size != right.size) return null
            var dot = 0.0
            var leftNorm = 0.0
            var rightNorm = 0.0
            for (index in left.indices) {
                val a = left[index].toDouble()
                val b = right[index].toDouble()
                if (!a.isFinite() || !b.isFinite()) return null
                dot += a * b
                leftNorm += a * a
                rightNorm += b * b
            }
            if (leftNorm <= EPSILON || rightNorm <= EPSILON) return null
            return (dot / (sqrt(leftNorm) * sqrt(rightNorm))).coerceIn(-1.0, 1.0).toFloat()
        }

        private fun squaredMagnitude(vector: FloatArray): Double =
            vector.sumOf { value -> value.toDouble() * value.toDouble() }

        private fun pairKey(left: Int, right: Int): Long {
            val first = minOf(left, right).toLong()
            val second = maxOf(left, right).toLong()
            return (first shl 32) or (second and 0xFFFF_FFFFL)
        }
    }
}
